argv:
$ErrorActionPreference='Continue'
$r=[ordered]@{}
$r.clock=(Get-Date).ToString('o')
$path='E:\WebAIBridge\app\worker-gemini-personal-attach-error.log'
$r.workerLogExists=Test-Path -LiteralPath $path -PathType Leaf
if($r.workerLogExists){
 $f=Get-Item -LiteralPath $path
 $r.workerLogInfo=@{length=$f.Length;modified=$f.LastWriteTime.ToString('o')}
 $lines=@(Get-Content -LiteralPath $path -Tail 95 -ErrorAction SilentlyContinue)
 $r.workerLog=@($lines|ForEach-Object{
  $s=[string]$_
  $s=[regex]::Replace($s,'(?i)(authorization|bearer|token|api.?key|password|cookie|secret|proxy.?user|session.?id)\s*[:=]\s*["'']?[^,;\s"''}]+','$1=[REDACTED]')
  $s=[regex]::Replace($s,'(?i)(https?://[^/\s]+)[^\s]*','$1/[PATH_REDACTED]')
  if($s.Length -gt 420){$s.Substring(0,420)}else{$s}
 })
}
$r.bridgeRepoPresent=Test-Path -LiteralPath 'E:\WebAIBridge\.git'
if($r.bridgeRepoPresent){$r.bridgeHead=((& git.exe -C 'E:\WebAIBridge' rev-parse --short HEAD 2>$null)-join '');$r.bridgePorcelainCount=@(& git.exe -C 'E:\WebAIBridge' status --porcelain=v1 -uno 2>$null).Count}
$p=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.Name -match '^(node|chrome|powershell)\.exe$'})
$r.processCounts=@{chrome=@($p|Where-Object{$_.Name -eq 'chrome.exe'}).Count;node=@($p|Where-Object{$_.Name -eq 'node.exe'}).Count;powershell=@($p|Where-Object{$_.Name -eq 'powershell.exe'}).Count}
$r.bridgeRelatedProcesses=@($p|Where-Object{$_.Name -eq 'node.exe' -and $_.CommandLine -match 'WebAIBridge'}|Select-Object -First 25|ForEach-Object{@{pid=$_.ProcessId;kind=if($_.CommandLine -match 'worker'){'worker'}else{'node-server'};port=if($_.CommandLine -match 'debugging-port[= ](\d+)'){$Matches[1]}else{''}}})
$r.cdpFlags=@($p|Where-Object{$_.Name -eq 'chrome.exe' -and $_.CommandLine -match 'remote-debugging-port=(\d+)'}|ForEach-Object{$Matches[1]}|Select-Object -Unique)
$r.ports=@(Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue|Where-Object{$_.LocalPort -in @(17448,17447,17410,17449,9222)}|ForEach-Object{@{port=$_.LocalPort;owner=$_.OwningProcess;address=$_.LocalAddress}})
foreach($u in @('http://127.0.0.1:17448/api/health','http://127.0.0.1:17448/v1/bridge/health')){
 try{$res=Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 3;$r[('http'+(($u -split '/')[4] -replace '[^a-z0-9]',''))]=@{status=[int]$res.StatusCode;bodyLength=$res.Content.Length}}catch{$r[('err'+(($u -split '/')[4] -replace '[^a-z0-9]',''))]=$_.Exception.GetType().Name}
}
$r|ConvertTo-Json -Compress -Depth 7
